import{localServiceClient,localFixturePassword}from"./local-fixtures.mjs";
export const operationalPersonas={admin:null,operations_admin:"operations_admin",privacy_reviewer:"privacy_reviewer",rights_reviewer:"rights_reviewer",archive_curator:"archive_curator",coordinator:"coordinator",facilitator:"facilitator",contribution_reviewer:"contribution_reviewer",image_reviewer:"image_reviewer",protocol_operator:"protocol_operator",result_editor:"result_editor",radio_editor:"radio_editor",art_editor:"art_editor",participant:null};
export const operationalPassword=localFixturePassword;export const operationalEmail=p=>`fixture-s33-2-${p.replaceAll("_","-")}@comun.test`;
export async function createOperationalPersonas(){const db=localServiceClient();const list=await db.auth.admin.listUsers({page:1,perPage:1000});for(const [persona,operational_role]of Object.entries(operationalPersonas)){const email=operationalEmail(persona);const old=list.data?.users.find(x=>x.email===email);if(old)await db.auth.admin.deleteUser(old.id);const{data,error}=await db.auth.admin.createUser({email,password:operationalPassword,email_confirm:true,user_metadata:{fixture:"s33-2",persona}});if(error||!data.user)throw new Error(error?.message??`auth ${persona}`);if(persona!=="participant"){await db.from("comun_admin_users").upsert({user_id:data.user.id,email,role:persona==="admin"?"admin":"viewer",is_active:true},{onConflict:"email"});await db.from("comun_admin_profiles").upsert({auth_user_id:data.user.id,email,display_name:`Fixture ${persona}`,role:persona==="admin"?"admin":"viewer",operational_role,active:true,operational_note:"fixture-s33-2"},{onConflict:"email"})}else await db.from("comun_member_profiles").upsert({user_id:data.user.id,display_name:"Participante fixture",participation_visibility:"private",status:"active",onboarding_completed_at:new Date().toISOString(),terms_version:"fixture",terms_accepted_at:new Date().toISOString(),privacy_version:"fixture",privacy_accepted_at:new Date().toISOString()},{onConflict:"user_id"})}return true}
export async function cleanupOperationalPersonas(){const db=localServiceClient();for(const persona of Object.keys(operationalPersonas)){const email=operationalEmail(persona);await db.from("comun_admin_profiles").delete().eq("email",email);await db.from("comun_admin_users").delete().eq("email",email)}const list=await db.auth.admin.listUsers({page:1,perPage:1000});for(const user of list.data?.users??[])if(user.email?.startsWith("fixture-s33-2-"))await db.auth.admin.deleteUser(user.id)}
